ndSet:"Remind",uxRemindCancel:"Don't remind",uxRemindOff:"Notifications are off for ContextFlow. Turn them on in Settings \u2192 Notifications \u2192 ContextFlow.",uxRemindAsk:"Open the ContextFlow app once and allow notifications, then set the reminder again.",uxRemindNone:"Reminders need the ContextFlow app on this device.",uxToday:"Today",uxTomorrow:"Tomorrow",uxRemindSaved:"Reminder: {0}",uxRemindNotSet:"Saved to the chat. Notifications are off for ContextFlow. Turn them on in Settings \u2192 Notifications \u2192 ContextFlow.",uxRemindNoApp:"Saved to the chat. Reminders need the ContextFlow app on this device.",uxUnpinAll:"Unpin all",setShareGroup:"Share and copy",uxShareMarks:"Highlights in shared text as **bold**",uxShareMarksHint:"Telegram, Notion and Slack show them in bold; Messages and Notes show the asterisks. Copy always keeps the bold.",nowOnPage:"Now on: {0}",retry:"Retry",askWithoutGoogle:"Ask without Google",thinking:"Reading the page\u2026",searching:"Searching Google\u2026",errNetwork:"No connection. Check your internet and try again.",errBusy:"ContextFlow is very busy right now. Please try again in a minute.",errUpstream:"The AI service didn't respond. Please try again.",errInterrupted:"The answer was interrupted.",errBadKey:"Your API key was rejected. Check it in Settings.",errGeneric:"Something went wrong. Please try again.",errSearchLimit:"You've reached the limit of Google answers for now. Regular answers still work.",errSearchUnavailable:"Google answers aren't available right now. Regular answers still work.",limitFreeTitle:"You've used today's free answers",limitProTitle:"Weekly limit reached",limitProBody:"Your Pro answers refresh in {0}.",longPageWeight:"Long page: answer \xD7{0}",longPageWeightHint:"This page is long: an answer about it counts as {0} answers of your limit.",limitLongTitle:"This page is long",limitLongBody:"An answer about it counts as {0}, and you have {1} left.",getPro:"Get Pro",useOwnKey:"Use my own API key",usageFree:"{0} of {1} free answers left today",usagePro:"Pro \xB7 {0} of {1} answers left this week",usageOwnKey:"Using your own API key",hours:"{0} h",minutes:"{0} min",consentTitle:"Before ContextFlow uses AI",consentBody:"You give it once, for all of ContextFlow's AI. Each feature sends only what it needs, when you use it, via our server to Anthropic (Claude), OpenAI (backup answers, suggestions) and Google Gemini (Google answers). With your own API key, it goes straight to that provider. Nothing is kept on our servers; no one trains on it.",consentAnswers:"Answers: your question, the page's text or your selection, and your \u201CAbout me\u201D if you wrote one. If Claude is unavailable, OpenAI answers; Google answers go to Google Gemini.",consentChats:"\u201CAsk your chats\u201D and AI search (Pro): short excerpts of your chats.",consentTemplates:"Templates: their text, to mark the blanks; the page's text for \u201CFill from the page\u201D; your words and the templates' titles for \u201CFind by meaning\u201D.",consentWatch:"Watching a page: what you selected, your words for when to tell you, the text around it and the page's title; later, the old and the new value.",consentSuggest:"Suggestions (Pro, only once you turn them on): the text of new questions, answers and notes, to OpenAI to compare them and to Claude to check a tag.",consentStored:"Your chats stay on your devices and, if you sync them, in your iCloud.",consentWhat:"What exactly is sent",consentAccept:"Agree and continue",consentAgainTitle:"Updated: one consent for all AI features",consentDecline:"Not now",consentNeeded:"Nothing was sent: AI answers need your consent first.",privacyPolicy:"Privacy Policy",setPlan:"Plan",planFree:"Free",planPro:"Pro",planByok:"Own key",planRenews:"Renews {0}",manageSubscription:"Manage subscription",restorePurchases:"Restore purchases",setAppearance:"Appearance",themeAuto:"Auto",themeLight:"Light",themeDark:"Dark",setTextSize:"Text size",sizeNormal:"Normal",sizeLarge:"Large",setFab:"Floating button",fabOn:"On",fabOff:"Off",setFabHint:"The \u2726 button opens ContextFlow on any site. Hide it on a single site with the link below, or turn it off here.",hideOnSite:"Hide on {0}",showOnSite:"Show on {0}",setSelectionButton:"Button when selecting text",setAbout:"About me",setAboutHint:"Optional. Helps tailor answers, e.g. \u201CI'm a product designer, keep it short\u201D.",setOwnKey:"Own API key (OpenAI or Claude)",setOwnKeyHint:"Included in Pro and Own key plans. Paste an OpenAI or Anthropic (Claude) key; requests go straight from your device to that provider.",setOwnKeyLocked:"Available with Pro or Own key plan",setOwnKeyModel:"Model",modelFast:"Fast",modelSmart:"Smart",setOwnKeyModelHint:"Fast: newest Claude Haiku or GPT mini. Smart: newest Claude Sonnet or GPT.",getKey:"Get a key",save:"Save",remove:"Remove",saved:"Saved",setSyncChats:"Sync chats with iCloud",setSyncChatsHint:"Continue a chat on your iPhone, iPad and Mac. The chat is end-to-end encrypted in your iCloud and never stored on our servers.",deleteChats:"Delete all chats",chatsDeleted:"Chats deleted",support:"Support",terms:"Terms of Use",rateApp:"Rate ContextFlow",version:"Version {0}",fabLabel:"Ask ContextFlow",selAsk:"Ask AI",selExplain:"Explain",selTranslate:"Translate",googleModeHint:"Answer with Google Search: fresh facts with sources",googleBadge:"Google Search",sources:rw,tourStep:"{0} of {1}",tourSkip:"Skip",tourNext:"Next",tourDone:"Got it",tourShow:"Show tips",tourAskTitle:"Ask about this page",tourAskBody:"ContextFlow reads the page you're on; with Pro, also the videos with captions and the PDFs on it. Pick an action like Summarize, or type your own question.",tourSelectTitle:"Only part of it?",tourSelectBody:"Select text on the page first, and the answer is about just that. A label over the field then shows what's selected.",tourGoogleTitle:"Fresh facts from Google",tourGoogleBody:"Turn this on to answer with Google Search: current information with sources.",tourChatsTi